steps.body:
A **subsequence** keeps some characters of a string, in order, and drops the rest: `one` is a subsequence of `stone`. The longest common subsequence (LCS) of two strings is the longest subsequence they share.

Let `dp[i][j]` be the LCS length of the first `i` characters of `a` and the first `j` of `b`. Compare the last characters of those two prefixes. If they match, that character can end the answer, so add 1 to `dp[i - 1][j - 1]`. If not, one of them is left out, so keep the better of dropping either: `std::max(dp[i - 1][j], dp[i][j - 1])`.

```cpp
std::string a = "stone";
std::string b = "longest";
int n = static_cast<int>(a.size());
int m = static_cast<int>(b.size());
std::vector<std::vector<int>> dp(n + 1, std::vector<int>(m + 1, 0));
for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j) {
        if (a[i - 1] == b[j - 1]) {
            dp[i][j] = dp[i - 1][j - 1] + 1;
        } else {
            dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);
        }
    }
}
std::cout << dp[n][m] << '\n';   // 3, for "one"
```

The outer vector copies the row `std::vector<int>(m + 1, 0)` into each of its n + 1 slots, so every row is its own buffer on the heap. Row 0 and column 0 stand for the empty prefixes, which share nothing, so they stay 0 and the loops start at 1. Row by row, the cells above, to the left, and up-left are filled before you need them.

There are (n + 1)(m + 1) cells and each takes constant work, so this is O(n * m) time and space. Two 1,000-character strings take a million `int`s, 4 MB.

example.code:
#include <algorithm>
#include <cstddef>
#include <iostream>
#include <string>
#include <utility>
#include <vector>

std::vector<std::vector<int>> lcsTable(const std::string& a, const std::string& b) {
    int n = static_cast<int>(a.size());
    int m = static_cast<int>(b.size());
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(m + 1, 0));
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    return dp;
}

void printTable(const std::string& a, const std::string& b, const std::vector<std::vector<int>>& dp) {
    std::cout << "   ";
    for (char ch : b) {
        std::cout << ' ' << ch;
    }
    std::cout << '\n';
    for (std::size_t i = 0; i < dp.size(); ++i) {
        std::cout << (i > 0 ? a[i - 1] : ' ');
        for (int v : dp[i]) {
            std::cout << ' ' << v;
        }
        std::cout << '\n';
    }
}

int main() {
    std::string a = "AGCAT";
    std::string b = "GAC";
    std::vector<std::vector<int>> dp = lcsTable(a, b);
    printTable(a, b, dp);
    std::cout << "Longest shared: " << dp[a.size()][b.size()] << '\n';

    std::vector<std::pair<std::string, std::string>> pairs = {{"GATTACA", "GCATGCT"}, {"AAAA", "TTTT"}};
    for (const auto& [x, y] : pairs) {
        std::cout << x << " and " << y << ": " << lcsTable(x, y)[x.size()][y.size()] << '\n';
    }
    return 0;
}

