                dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    return dp;
}

std::string rebuild(const std::string& a, const std::string& b, const std::vector<std::vector<int>>& dp) {
    int i = static_cast<int>(a.size());
    int j = static_cast<int>(b.size());
    std::string out;
    while (i > 0 && j > 0) {
        if (a[i - 1] == b[j - 1]) {
            out += a[i - 1];
            --i;
            --j;
        } else if (dp[i - 1][j] >= dp[i][j - 1]) {
            --i;
        } else {
            --j;
        }
    }
    std::reverse(out.begin(), out.end());
    return out;
}

int main() {
    std::vector<std::pair<std::string, std::string>> pairs = {
        {"AGCAT", "GAC"}, {"GATTACA", "GCATGCT"}, {"AAAA", "TTTT"}};
    for (const auto& [a, b] : pairs) {
        std::string shared = rebuild(a, b, lcsTable(a, b));
        std::cout << a << " and " << b << ": " << (shared.empty() ? "none" : shared) << '\n';
    }
    return 0;
}

