#include <string>
#include <utility>
#include <vector>

std::vector<std::vector<int>> editTable(const std::string& a, const std::string& b) {
    int n = static_cast<int>(a.size());
    int m = static_cast<int>(b.size());
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(m + 1, 0));
    for (int i = 0; i <= n; ++i) {
        dp[i][0] = i;
    }
    for (int j = 0; j <= m; ++j) {
        dp[0][j] = j;
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 1 + std::min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]});
            }
        }
    }
    return dp;
}

void printTable(const std::string& a, const std::string& b, const std::vector<std::vector<int>>& dp) {
    std::cout << "   ";
    for (char ch : b) {
        std::cout << ' ' << ch;
    }
    std::cout << '\n';
    for (std::size_t i = 0; i < dp.size(); ++i) {
        std::cout << (i > 0 ? a[i - 1] : ' ');
        for (int v : dp[i]) {
            std::cout << ' ' << v;
        }
        std::cout << '\n';
    }
}

int main() {
