    printTable(a, b, dp);
    std::cout << a << " to " << b << ": " << dp[a.size()][b.size()] << '\n';

    std::vector<std::pair<std::string, std::string>> pairs = {{"sunday", "saturday"}, {"same", "same"}};
    for (const auto& [x, y] : pairs) {
        std::cout << x << " to " << y << ": " << editTable(x, y)[x.size()][y.size()] << '\n';
    }
    return 0;
}

